// Super Admin AIOS Task Intake & Kāraka Decomposition
const payload = $input.item.json.body || $input.item.json;

const task = {
  taskId: payload.taskId || 'AIOS-' + Date.now(),
  subject: payload.subject || 'Mathematics',
  grade: payload.grade || 8,
  topic: payload.topic || 'Rational Numbers',
  action: payload.action || 'BUILD_CHAPTER',
  mode: payload.mode || 'FULL_AUTOMATION',
  gate: payload.action === 'PROMOTE_RELEASE' ? 'GATE_6' : 'ROUTINE',
  timestamp: new Date().toISOString()
};

return [{
  json: {
    task,
    status: 'INGESTED',
    staff_agents: [
      { id: 'AGT-001', name: 'IngestAgent', status: 'READY' },
      { id: 'AGT-002', name: 'AnalysisAgent', status: 'READY' },
      { id: 'AGT-003', name: 'DesignAgent', status: 'READY' },
      { id: 'AGT-004', name: 'AssessmentAgent', status: 'READY' },
      { id: 'AGT-005', name: 'LLEAgent', status: 'READY' },
      { id: 'AGT-006', name: 'QAAgent', status: 'READY' },
      { id: 'AGT-007', name: 'BrowserTesterAgent', status: 'READY' }
    ]
  }
}];

// Step 1: IngestAgent & AnalysisAgent Dispatch
const input = $input.item.json;
const task = input.task;

return [{
  json: {
    ...input,
    stage: 'ANALYSIS',
    ingest_result: {
      agent: 'IngestAgent',
      syllabus: `NCERT ${task.subject} Class ${task.grade}`,
      extracted_sections: 5,
      status: 'SUCCESS'
    },
    analysis_result: {
      agent: 'AnalysisAgent',
      competencies: ['Concept Definition', 'Visual Representation', 'Misconception Resolution'],
      diagnostic_misconceptions: ['Sign inversion error', 'Denominator confusion'],
      status: 'SUCCESS'
    }
  }
}];

// Step 2: DesignAgent (Foundation Matching & Local CDN Assets) & AssessmentAgent
const input = $input.item.json;
const task = input.task;

return [{
  json: {
    ...input,
    stage: 'DESIGN_AND_ASSESSMENT',
    design_result: {
      agent: 'DesignAgent',
      matched_foundation: 'F01 Escape Run / MicroSims F02',
      prestack_interactive: 'AVR-P301 (Number Line Marker)',
      local_cdn_path: 'assets/cdn/interactives/AVR-P301-number-line-marker.html',
      mobile_viewport_clamped: true,
      status: 'MATCHED'
    },
    assessment_result: {
      agent: 'AssessmentAgent',
      hints_stages: ['Attention', 'Relationship', 'Strategy', 'Procedure'],
      spoiler_risk: 'ZERO',
      status: 'COMPILED'
    }
  }
}];

// Step 3: LLEAgent (Math Insulation & Bilingual Linking)
const input = $input.item.json;

return [{
  json: {
    ...input,
    stage: 'LLE_INSULATION',
    lle_result: {
      agent: 'LLEAgent',
      math_insulated_variables: 18,
      bilingual_tokens_wrapped: 42,
      dictionary_db: 'aasha_dictionary_db.json',
      offline_tts_ready: true,
      status: 'INSULATED'
    }
  }
}];

// Step 4: QAAgent & BrowserTesterAgent (Dual-Benchmark Certification)
const input = $input.item.json;

return [{
  json: {
    ...input,
    stage: 'VERIFICATION',
    qa_result: {
      agent: 'QAAgent',
      ltruth_score: '100/100',
      spoiler_leaks: 0,
      math_rt_collisions: 0,
      status: 'CERTIFIED'
    },
    browser_result: {
      agent: 'BrowserTesterAgent',
      console_errors: 0,
      touch_targets_ge_44px: true,
      same_frame_mobile_fits: true,
      status: 'PASS'
    }
  }
}];

// HIL Instant Review Boundary
const input = $input.item.json;
return [{
  json: {
    taskId: input.task.taskId,
    state: 'HIL_REVIEW_PENDING',
    reviewPrompt: 'Gate 6: Super Admin instant review required before git push to remote.',
    deliverable_summary: {
      subject: input.task.subject,
      topic: input.task.topic,
      ltruth_score: input.qa_result.ltruth_score,
      browser_status: input.browser_result.status
    },
    hil_policy: 'Instant single-click review by Super Admin',
    timestamp: new Date().toISOString()
  }
}];

// Autonomous Routine Task Completion (Full Access Pre-Authorized)
const input = $input.item.json;
return [{
  json: {
    taskId: input.task.taskId,
    state: 'COMPLETED_AUTOMATICALLY',
    message: 'Routine autonomous task executed with full access. Zero interruptions.',
    deliverables: {
      interactive: input.design_result.local_cdn_path,
      qa_score: input.qa_result.ltruth_score,
      browser_test: input.browser_result.status
    },
    timestamp: new Date().toISOString()
  }
}];
